changeSet.sql:
CREATE UNIQUE INDEX uk_analytics_revision_current_published
    ON analytics_revision(model, model_id)
 WHERE status = 'PUBLISHED';

CREATE OR REPLACE FUNCTION public.set_analytics_revision_legacy_defaults()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF NEW.version_no IS NULL THEN
        PERFORM pg_advisory_xact_lock(
            hashtext(COALESCE(NEW.model, '') || ':' || COALESCE(NEW.model_id::text, ''))::bigint
        );
        SELECT COALESCE(MAX(version_no), 0) + 1
          INTO NEW.version_no
          FROM public.analytics_revision
         WHERE model IS NOT DISTINCT FROM NEW.model
           AND model_id IS NOT DISTINCT FROM NEW.model_id;
    END IF;
    IF NEW.status IS NULL THEN
        NEW.status := 'DRAFT';
    END IF;
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_analytics_revision_legacy_defaults ON public.analytics_revision;
CREATE TRIGGER trg_analytics_revision_legacy_defaults
    BEFORE INSERT ON public.analytics_revision
    FOR EACH ROW
    EXECUTE FUNCTION public.set_analytics_revision_legacy_defaults();

UPDATE analytics_dashboard
   SET lifecycle_status = CASE WHEN archived THEN 'ARCHIVED' ELSE 'DRAFT' END,
       registration_status = 'NOT_REGISTERED'
 WHERE lifecycle_status IS NULL OR registration_status IS NULL;
ALTER TABLE analytics_dashboard
    ADD CONSTRAINT ck_analytics_dashboard_lifecycle
    CHECK (lifecycle_status IN ('DRAFT', 'PUBLISHED', 'ARCHIVED'));
ALTER TABLE analytics_dashboard
    ADD CONSTRAINT ck_analytics_dashboard_registration
    CHECK (registration_status IN ('NOT_REGISTERED', 'PENDING_REGISTRATION', 'AVAILABLE', 'REGISTRATION_FAILED', 'DISABLED'));
